clamp_faqs=[
('What does a CSS clamp generator do?','A CSS clamp generator calculates a value that grows between a minimum and maximum size over a chosen viewport range, then produces a CSS clamp(minimum, preferred, maximum) expression.'),
('How is the preferred clamp value calculated?','The tool calculates a linear slope from the difference between the size endpoints and the viewport endpoints, then calculates an intercept that meets the minimum at the smaller viewport. The preferred expression combines that intercept with a viewport-relative vw term.'),
('Should I use rem or px in clamp()?','For text and scalable spacing, rem bounds and an rem intercept can better respect the user’s root font size. Pixel output can still be useful for some fixed design-system values; test your choice with browser zoom and user font-size settings.'),
('Can I use clamp() for padding, margin and gap?','Yes. It works in properties that accept compatible numeric or length values, including font-size, padding, margin, gap, width and border-radius.'),
('What viewport range should I enter?','Use the viewport widths where you want the value to reach the specified minimum and maximum. A common starting point is 360px to 1440px, but choose the range that matches your design and test smaller and larger screens.'),
('Does CSS clamp replace every media query?','No. It is useful for continuously scaling a value between bounds. Media queries and container queries are still appropriate when layout structure or component behavior must change at a condition.')]
clamp_body=f'''
<section class="page-hero clamp"><div class="wrap split-hero"><div><div class="eyebrow light">Tool 002 / Fluid CSS</div><h1>Responsive values.<br><span style="color:var(--acid)">Calculated, not guessed.</span></h1><p class="lead">A CSS clamp calculator for fluid typography, spacing and layout values. Set your size limits, choose the viewport range, preview the result and copy the CSS you actually need.</p><div class="page-meta"><span>Live calculation</span><span>px or rem output</span><span>Copy-ready CSS</span></div></div><div class="hero-aside"><span class="aside-label">A single fluid rule</span><div class="code-large" style="font-size:clamp(19px,3vw,31px)">clamp(<span style="color:#ffad94">min</span>,<br>&nbsp;&nbsp;<span style="color:var(--acid)">preferred</span>,<br>&nbsp;&nbsp;<span style="color:var(--blue)">max</span>)</div><p class="aside-small">Keep the result within bounds while a viewport-relative value scales in between. The generator calculates the intercept and vw slope from your endpoints.</p><div class="code-band"><span>MINIMUM</span><span>FLUID RANGE</span><span>MAXIMUM</span></div></div></div></section>
<section class="clamp-tool-section"><div class="wrap"><div class="section-heading"><div><div class="eyebrow">Fluid value / live calculator</div><h2>Give it the limits.<br>Take the guesswork out.</h2></div><p>Change the size endpoints, viewport boundaries or output unit. The CSS and preview update locally as you adjust the values.</p></div><div class="clamp-layout"><section class="settings-panel" aria-labelledby="clamp-settings-title"><div class="settings-header"><h2 id="clamp-settings-title">Generator settings</h2><span>INPUT / 01</span></div><div class="settings-body"><div class="preset-list" role="group" aria-label="Use a preset"><button class="preset" type="button" data-clamp-preset="body" aria-pressed="false">Body text</button><button class="preset" type="button" data-clamp-preset="heading" aria-pressed="false">Large heading</button><button class="preset" type="button" data-clamp-preset="section" aria-pressed="false">Section spacing</button><button class="preset" type="button" data-clamp-preset="gap" aria-pressed="false">Layout gap</button><button class="preset" type="button" data-clamp-preset="radius" aria-pressed="false">Border radius</button></div><div class="form-grid"><div class="form-field"><label for="clamp-min">Minimum size</label><input id="clamp-min" type="number" min="0" step="0.05" value="1" inputmode="decimal"></div><div class="form-field"><label for="clamp-max">Maximum size</label><input id="clamp-max" type="number" min="0" step="0.05" value="3" inputmode="decimal"></div><div class="form-field"><label for="clamp-unit">Size unit</label><select id="clamp-unit"><option value="rem" selected>rem</option><option value="px">px</option></select></div><div class="form-field"><label for="clamp-property">CSS property</label><select id="clamp-property"><option value="font-size" selected>font-size</option><option value="padding">padding</option><option value="padding-block">padding-block</option><option value="padding-inline">padding-inline</option><option value="margin-block">margin-block</option><option value="gap">gap</option><option value="border-radius">border-radius</option><option value="width">width</option></select></div><div class="form-divider"></div><div class="form-field"><label for="clamp-min-vp">Minimum viewport (px)</label><input id="clamp-min-vp" type="number" min="1" step="1" value="360" inputmode="numeric"></div><div class="form-field"><label for="clamp-max-vp">Maximum viewport (px)</label><input id="clamp-max-vp" type="number" min="1" step="1" value="1440" inputmode="numeric"></div><div class="form-field"><label for="clamp-root">Root font size (px)</label><input id="clamp-root" type="number" min="1" max="200" step="1" value="16" inputmode="numeric"></div><div class="form-field"><label for="clamp-precision">Decimal places</label><select id="clamp-precision"><option value="2">2 places</option><option value="3">3 places</option><option value="4" selected>4 places</option><option value="5">5 places</option><option value="6">6 places</option></select></div></div><p id="clamp-status" class="form-note" role="status" aria-live="polite">Calculation updates as you type.</p><div class="field-actions" style="margin-top:16px"><button type="button" class="action-btn" id="clamp-reset">Reset values</button></div></div></section><section class="output-panel" aria-labelledby="clamp-output-title"><div class="output-header"><h2 id="clamp-output-title">Generated CSS</h2><span>OUTPUT / 02</span></div><div class="output-body"><div class="output-code"><span class="output-label">CSS declaration</span><code id="clamp-declaration">font-size: clamp(1rem, calc(0.3333rem + 2.963vw), 3rem);</code></div><div class="output-actions"><button type="button" class="action-btn primary" id="clamp-copy">Copy CSS</button><button type="button" class="action-btn" id="clamp-download">Download .css</button></div><div class="preview-stage"><div class="preview-toolbar"><label for="clamp-preview-width">PREVIEW VIEWPORT</label><span id="clamp-preview-width-label" class="preview-width">768px</span></div><div class="preview-toolbar" style="border-top:0"><input id="clamp-preview-width" type="range" min="320" max="1920" step="10" value="768" aria-label="Preview viewport width in pixels"></div><div class="preview-canvas"><div id="clamp-preview-object" class="preview-object"><p class="preview-title" id="clamp-preview-title">Make space for ideas.</p><p class="preview-copy">Fluid values move with the viewport, then stop at the bounds you defined. One rule; fewer breakpoint overrides.</p><span class="preview-chip">clamp() / live preview</span></div></div></div><div class="calculated-value"><span>Calculated value at preview width</span><strong id="clamp-evaluated">1.7556rem at 768px</strong></div><div class="tailwind-block"><div class="field-label"><span>Tailwind-style arbitrary value</span><button type="button" class="action-btn btn-small" id="clamp-copy-tailwind">Copy</button></div><div class="tailwind-output" id="clamp-tailwind">fontSize:[clamp(1rem,calc(0.3333rem+2.963vw),3rem)]</div><p class="form-note">The snippet is a starting point. Confirm the syntax against your Tailwind version and the property you are styling.</p></div></div></section></div></div></section>
<section class="content-section"><div class="wrap content-grid"><aside class="content-aside"><div class="eyebrow">Understand the formula</div><h2>One minimum. One maximum. A fluid middle.</h2><p>The calculator does the slope and intercept arithmetic; understanding those pieces makes it easier to choose sensible endpoints.</p><a class="text-link" href="/blog/css-clamp-calculator/">Read the formula guide <span>↗</span></a></aside><div class="content-main"><div class="answer-card"><strong>What does clamp() do?</strong><code class="inline-code">clamp(minimum, preferred, maximum)</code> uses the preferred value while it sits between the bounds, but never resolves below the minimum or above the maximum. The preferred expression can be a fixed value, a viewport calculation or another valid CSS expression.</div><h2 id="formula">How a CSS clamp calculator works</h2><p>To create a linear fluid value, the generator finds the slope between two desired size/viewport points. It then calculates the intercept so the preferred expression equals the minimum size at the minimum viewport. The bounds protect the value outside the range.</p><div class="code-block"><div class="code-top"><span>THE CALCULATION / CONCEPT</span><span>LINEAR SCALE</span></div><pre>change in size (px)
÷ change in viewport width (px)
× 100 = vw coefficient

intercept (px)
= minimum size (px)
− (vw coefficient ÷ 100 × minimum viewport)

clamp(minimum, calc(intercept + coefficient × 1vw), maximum)</pre></div><p>For a 1rem minimum and 3rem maximum over 360px to 1440px, with a 16px root size, the calculated preferred value is approximately <code class="inline-code">calc(0.3333rem + 2.963vw)</code>. The full expression is <code class="inline-code">clamp(1rem, calc(0.3333rem + 2.963vw), 3rem)</code>. At the endpoints, the preferred expression meets the requested size; outside the range, the minimum or maximum takes over.</p><h2 id="units">Should the generator output rem or px?</h2><p>For fluid typography, rem is a strong default because it relates to the root font size and can preserve scaling when users change their browser settings. Pixel-based values can be appropriate in some layout contexts, but don’t assume a fixed unit is accessible simply because its numerical value looks correct on your own screen.</p><p>CSS `clamp()` has broad modern-browser support. Still test your results with keyboard navigation, zoom, text enlargement and the real content that will use the rule. A mathematically smooth scale can still be a poor design decision if the minimum is too small or the maximum creates an awkward line length.</p><h2 id="where-to-use">Where can you use a fluid value?</h2><p>Use clamp for any property that accepts an appropriate length, such as font size, padding, margin, gap, width and border radius. Choose the property before you copy the output: a value designed for a type scale may not make sense as a width or spacing token.</p><h2 id="when-not-to">When not to use clamp()</h2><p>Clamp changes a value continuously between bounds. It doesn't choose a new layout structure. If a navigation bar needs to turn into a menu, a multi-column layout needs to stack, or component behavior changes at a breakpoint, media queries or container queries remain useful. A fluid value and a breakpoint-driven layout can work together.</p><p>For worked typography scales and accessibility notes, read the <a href="/blog/fluid-typography/">fluid typography guide</a>. For a property-by-property collection, use the <a href="/blog/css-clamp-examples/">CSS clamp examples</a>.</p></div></div></section>
<section class="faq-wrap"><div class="wrap"><div><div class="eyebrow">FAQ / CSS clamp</div><h2>Questions about fluid values.</h2><p class="muted small">Use the calculator as a tool, not a substitute for testing.</p></div><div class="faq-list">{''.join(f'<details><summary>{esc(q)}</summary><p>{esc(a)}</p></details>' for q,a in clamp_faqs)}</div></div></section>
<section class="section white tight"><div class="wrap"><div class="cta-panel"><div><div class="eyebrow">Next / Typography</div><h2>Make responsive type feel intentional.</h2><p>Learn how to choose the type size range, viewport endpoints and rem-based values for a readable fluid scale.</p></div><a class="btn btn-dark" href="/blog/fluid-typography/">Read fluid typography ↗</a></div></div></section>'''
clamp_schema={"@context":"https://schema.org","@type":"WebApplication","name":"CSS Clamp Generator and Calculator","url":BASE+"/css-clamp-generator/","applicationCategory":"DeveloperApplication","operatingSystem":"Any modern browser","isAccessibleForFree":True,"browserRequirements":"JavaScript enabled","description":"Calculate fluid CSS clamp values from size bounds and viewport widths, with live preview and copyable output."}
write('css-clamp-generator/index.html',page('CSS Clamp Generator & Calculator — Fluid Typography and Spacing | DevArea Tools','Free CSS clamp generator and calculator. Create responsive font sizes and spacing from minimum and maximum values, choose viewport bounds, preview fluid CSS, and copy the result.','/css-clamp-generator/',clamp_body,active='/css-clamp-generator/',schemas=[org_schema(),clamp_schema,faq_schema(clamp_faqs),breadcrumb_schema([('Home','/'),('CSS clamp generator','/css-clamp-generator/')])],extra_scripts=['/assets/core.js','/assets/clamp.js']))

