articles=[]
def add_article(slug,title,meta,description,category,minutes,updated,sections,faqs,sources,keywords):
    articles.append(dict(slug=slug,title=title,meta=meta,description=description,category=category,minutes=minutes,updated=updated,sections=sections,faqs=faqs,sources=sources,keywords=keywords))

add_article('jwt-token-parts','JWT Token Parts Explained: Header, Payload & Signature','JWT Token Parts Explained: Header, Payload and Signature','Learn the three parts of a JWT token, how Base64url encoding works, what header and payload claims mean, and why decoding does not verify a signature.','JWT / Structure',7,'28 October 2026',[
('the-three-parts','What are the three parts of a JWT token?', '''<p>A typical signed compact JSON Web Token (JWT) has three segments separated by periods:</p><div class="code-block"><div class="code-top"><span>COMPACT SERIALIZATION</span><span>3 SEGMENTS</span></div><pre>BASE64URL(header).BASE64URL(payload).BASE64URL(signature)</pre></div><p>The first segment is the protected header. The second is the claims payload. The last segment contains the cryptographic signature or message authentication code for a signed token. The periods are structural separators, not part of any individual segment.</p><p>This is the common compact representation of a signed JWT (a JWS). Encrypted compact JWTs (JWE) have a different five-part structure, so a three-part decoder should explain that distinction instead of treating every token as the same format.</p>'''),
('header','Part 1: the JWT header', '''<p>The header is JSON describing the protected token metadata. Common members include <code class="inline-code">alg</code>, which identifies the cryptographic algorithm used for signing, and <code class="inline-code">typ</code>, which can indicate that the object is a JWT. Some systems include <code class="inline-code">kid</code>, a key identifier used by a verifier to select a key from a trusted set.</p><div class="code-block"><div class="code-top"><span>HEADER EXAMPLE</span><span>JSON</span></div><pre>{
  "alg": "HS256",
  "typ": "JWT",
  "kid": "key-2026-01"
}</pre></div><p>These values are data from the token, not a source of trust. A verifier must apply an allowed algorithm policy and resolve keys through trusted configuration. It must not accept an algorithm just because the incoming header asks for it.</p>'''),
('payload','Part 2: the JWT payload', '''<p>The payload contains claims: statements represented as name/value pairs. Registered claims include issuer, subject, audience and time-related values. Applications can also use public or private claim names for domain-specific information. Registered claims are not automatically mandatory in every JWT; the application defines which claims are required and how they are interpreted.</p><div class="code-block"><div class="code-top"><span>PAYLOAD EXAMPLE</span><span>JSON</span></div><pre>{
  "iss": "https://identity.example.test",
  "sub": "user-42",
  "aud": "orders-api",
  "iat": 1767225600,
  "exp": 1893456000,
  "role": "reader"
}</pre></div><p>Because Base64url is an encoding, not encryption, do not place secrets or data that must remain confidential in an ordinary signed JWT payload. Anyone who gets the token may be able to read the claims. Use a different architecture or an encrypted token format when confidentiality is required.</p>'''),
('signature','Part 3: the signature segment', '''<p>The signature protects the encoded header and payload against undetected modification when it is correctly generated and verified. For an HMAC algorithm, the signature uses a shared secret; for an asymmetric algorithm, the issuer signs with a private key and the verifier checks with a corresponding public key.</p><p>A formatter can show the signature segment, but that is not the same as checking it. Verification needs a trusted key, a configured algorithm allowlist and the application's validation policy. It is also common to validate issuer, audience, expiry and authorization conditions after signature verification.</p><div class="notice"><strong>The distinction to remember</strong>A token that decodes successfully can still be expired, tampered with, meant for a different audience or invalid under your application's policy.</div>'''),
('base64url','What Base64url means in a JWT', '''<p>JWT compact serialization uses Base64url encoding for the JSON header and payload. Compared with standard Base64, Base64url uses hyphen (<code class="inline-code">-</code>) and underscore (<code class="inline-code">_</code>) where standard Base64 uses plus and slash. Padding is commonly omitted in compact serialization. The encoded text is designed to travel safely in URLs and HTTP contexts.</p><p>Decoding reverses the encoding to reveal the JSON bytes. It does not decrypt the value, verify a signature or establish the identity of the issuer. A useful formatter should therefore display the decoded JSON while clearly stating what remains unchecked.</p>'''),
('errors','Common JWT structure errors', '''<ul><li><b>Two or four segments:</b> a dot may be missing or the value may not be a standard three-part compact JWS.</li><li><b>Five segments:</b> it may be a compact JWE, which needs decryption and appropriate keys instead of a simple payload decoder.</li><li><b>Base64url failure:</b> the value may be truncated, copied with invalid characters, or changed by an application that wrapped the token.</li><li><b>JSON parse failure:</b> a segment can decode to text that is not a JSON object.</li><li><b>Unexpected claim:</b> the claim may be application-specific or optional. Check the issuing system and the protocol you are using.</li></ul><p>Paste a test token into the <a href="/jwt-tools/">DevArea JWT inspector</a> to see each segment separately. For claim meanings, continue to the <a href="/blog/jwt-fields/">JWT fields reference</a>.</p>''')],
[
('Can a JWT have only two parts?','A signed compact JWS JWT normally has three dot-separated segments. Some unsecured JWT representations can have an empty signature segment, but they still have two periods. A two-segment value is not the usual compact serialization.'),
('Are JWT payloads encrypted?','Not by default. A signed JWT payload is Base64url-encoded, not encrypted. Anyone who obtains the token can generally decode its claims.'),
('Does decoding all three parts prove a token is valid?','No. Decoding reveals data. A verifier must check the signature with trusted key material and validate the claims and policies expected by the application.'),
('What is the difference between JWT and JWE?','JWT is the claims format. JWS is commonly used for signed compact JWTs with three segments. JWE is used for encrypted content and its compact serialization generally contains five segments.')],
[('RFC 7519 — JSON Web Token','https://datatracker.ietf.org/doc/html/rfc7519'),('OWASP JSON Web Token Cheat Sheet','https://cheatsheetseries.owasp.org/cheatsheets/JSON_Web_Token_for_Java_Cheat_Sheet.html'),('RFC 8725 — JSON Web Token Best Current Practices','https://www.rfc-editor.org/rfc/rfc8725.html')],
['jwt token parts','parts of a jwt token','jwt structure','jwt format','what does a jwt look like'])

add_article('jwt-token-format','JWT Token Format: How the Compact String Works','JWT Token Format Explained: Structure, Encoding and Examples','Understand the JWT token format, the three dot-separated segments, Base64url encoding, common errors, and how to format a token as readable JSON.','JWT / Format',7,'28 October 2026',[
('quick-answer','What is the JWT token format?', '''<p>A common signed JSON Web Token is serialized as three Base64url-oriented segments separated by periods: <code class="inline-code">header.payload.signature</code>. The header and payload encode JSON objects; the signature segment carries a cryptographic value. The dots delimit the segments.</p><p>A compact token is intentionally dense for transport. A JWT formatter makes the header and claims readable, but the formatted JSON is only an inspection view—it doesn't prove who issued the token or whether its signature is correct.</p>'''),
('format-example','A JWT format example', '''<div class="code-block"><div class="code-top"><span>ILLUSTRATIVE TOKEN SHAPE</span><span>NOT A CREDENTIAL</span></div><pre>eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9
.
eyJzdWIiOiJkZW1vIiwiaWF0IjoxNzY3MjI1NjAwfQ
.
ZGVtby1zaWduYXR1cmU</pre></div><p>Line breaks are shown here only to make the three parts easier to see; a compact token is normally pasted as one continuous string. The example's signature text is illustrative and must not be interpreted as a valid signature for a real service.</p>'''),
('base64url-format','Base64url encoding and padding', '''<p>In the compact representation, the header and payload are Base64url-encoded. This variation replaces <code class="inline-code">+</code> with <code class="inline-code">-</code> and <code class="inline-code">/</code> with <code class="inline-code">_</code>; padding characters are omitted in the JWS compact representation. A decoder may need to restore padding internally before using a general Base64 decoder.</p><p>Encoding is not encryption. The payload may contain names, IDs, roles or timestamps, so treat a token as sensitive even when its contents are easy to read. Avoid writing raw tokens to logs, sharing them in support tickets, or including them in screenshots.</p>'''),
('format-vs-validate','Formatting is not validation', '''<p>A formatter turns encoded JSON into readable JSON and may translate NumericDate claims such as <code class="inline-code">exp</code>, <code class="inline-code">nbf</code> and <code class="inline-code">iat</code> into dates. A validator does more: it checks cryptographic integrity with a trusted key and applies required issuer, audience, time and application rules.</p><p>Even a tool that offers validation can only produce a meaningful result when it has the correct verification key and expected policy. A generic decoder without those inputs should never label a token “valid” simply because its JSON parses.</p>'''),
('troubleshooting-format','Why a JWT may not decode', '''<ul><li><b>Copying extra text:</b> remove surrounding quotes and unrelated labels. If the copied value begins with <code class="inline-code">Bearer</code>, a tool may accept it as an authorization prefix.</li><li><b>Incorrect number of periods:</b> signed compact tokens commonly contain two periods separating three segments; encrypted compact JWE uses a different five-segment structure.</li><li><b>Malformed Base64url:</b> a segment may have been truncated or transformed by a transport layer.</li><li><b>Not JSON:</b> the decoded bytes must parse as a JSON object for the header and claims set.</li><li><b>Wrong token type:</b> an opaque access token or another protocol value may look like a string but is not a JWT.</li></ul><p>Use the <a href="/jwt-tools/">JWT formatter</a> to inspect structure, then read the <a href="/blog/jwt-token-parts/">JWT token parts guide</a> to understand each segment.</p>'''),
('format-safely','A safer JWT debugging workflow', '''<ol><li>Use a development token or a controlled test value when possible.</li><li>Decode the header and payload to inspect fields and timestamps.</li><li>Compare the issuer, audience and time claims with the expected integration contract.</li><li>Validate the signature and claims with the same maintained library and configuration used by the application.</li><li>Never change authorization decisions based only on values displayed by a formatter.</li></ol><p>If the token appears structurally correct but an API still rejects it, investigate key rotation, clock skew, issuer/audience mismatch and the server-side validation policy.</p>''')],
[
('What characters separate the parts of a JWT?','Periods separate the segments in compact JWT serialization.'),
('Is a JWT Base64 or Base64url?','Compact JWT/JWS components use Base64url encoding, a URL-safe variation of Base64 with hyphen and underscore replacements and omitted padding.'),
('Can a JWT formatter fix a broken token?','It can help locate structure, encoding or JSON errors. It cannot reconstruct missing original bytes or prove a token is authentic.'),
('Does a JWT formatter need a secret key?','No key is needed simply to decode and format the header and payload. A correct key and verification policy are needed to verify a signature.')],
[('RFC 7519 — JSON Web Token','https://datatracker.ietf.org/doc/html/rfc7519'),('OWASP JSON Web Token Cheat Sheet','https://cheatsheetseries.owasp.org/cheatsheets/JSON_Web_Token_for_Java_Cheat_Sheet.html'),('JWT.io debugger','https://www.jwt.io/')],
['jwt token format','json web token structure','jwt formatter','jwt token structure'])

add_article('jwt-fields','JWT Fields Explained: iss, sub, aud, exp, nbf, iat and jti','JWT Fields Explained: A Practical Claims Reference','A practical JWT fields reference covering iss, sub, aud, exp, nbf, iat and jti, their meanings, common timestamp pitfalls, and what applications must validate.','JWT / Claims',8,'28 October 2026',[
('what-are-jwt-fields','What are JWT fields?', '''<p>JWT fields are usually called <em>claims</em>: name/value pairs in the payload that communicate information to the system consuming the token. The JWT specification defines registered names, but it does not make every registered claim mandatory for every token. The expected claims and their meaning depend on the application and protocol.</p><p>The following table summarizes the standard registered claim names most developers encounter. Treat their presence and value as input to a verifier's policy, not as proof of trust by themselves.</p>'''),
('registered-claims','Common registered JWT claims', '''<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Field</th><th>Meaning</th><th>Practical note</th></tr></thead><tbody><tr><td><code>iss</code></td><td>Issuer</td><td>Identifies the principal that issued the token. Compare it with a trusted expected issuer.</td></tr><tr><td><code>sub</code></td><td>Subject</td><td>Identifies the subject. The application defines the expected interpretation.</td></tr><tr><td><code>aud</code></td><td>Audience</td><td>Identifies the intended recipient or recipients. Reject a token not intended for the current recipient when audience validation is required.</td></tr><tr><td><code>exp</code></td><td>Expiration time</td><td>Token must not be accepted on or after this NumericDate under normal rules.</td></tr><tr><td><code>nbf</code></td><td>Not before</td><td>Token must not be accepted before this NumericDate under normal rules.</td></tr><tr><td><code>iat</code></td><td>Issued at</td><td>Time the token was issued. It is not automatically proof of freshness or validity.</td></tr><tr><td><code>jti</code></td><td>JWT ID</td><td>Identifier for this token; systems may use it for tracking or replay-related controls.</td></tr></tbody></table></div>'''),
('time-fields','JWT time fields: exp, nbf and iat', '''<p>The common time claims use NumericDate values—typically seconds from the Unix epoch, 1 January 1970 UTC. A decoder that interprets the number as milliseconds will show a wildly incorrect date, so inspect the unit before troubleshooting.</p><ul><li><b><code>exp</code>:</b> the token must not be accepted on or after the expiration time, subject to any explicitly configured small clock-skew allowance.</li><li><b><code>nbf</code>:</b> the token should not be accepted before the not-before time.</li><li><b><code>iat</code>:</b> records when the token was issued. Application policy can use it to evaluate age, but its presence does not validate the token.</li></ul><p>A browser-based inspector can compare numeric dates with the local clock to surface likely timing issues. A production verifier must use its own trusted time and validation configuration.</p>'''),
('custom-claims','Custom JWT fields', '''<p>Tokens often contain application-specific fields such as <code class="inline-code">role</code>, <code class="inline-code">tenant</code>, <code class="inline-code">permissions</code> or a feature flag. Those names are not automatically registered claims. Their meaning comes from the issuer-consumer contract, and the server must apply the required authorization rules.</p><p>Do not infer a user’s privileges from an unverified <code class="inline-code">role</code> field displayed by a decoder. Claims become useful for security decisions only within a correctly validated token and authorization design.</p>'''),
('validate-fields','Which JWT fields should an application validate?', '''<p>There is no one list that fits every JWT. The application should define required claims for its use case and validate their type, value and semantics after verifying the signature. Common checks include trusted issuer, intended audience, expiry, not-before time and any application-specific requirements. For access tokens, also follow the applicable OAuth/OIDC profile and current security guidance.</p><p>Pin allowed algorithms in verifier configuration. Do not dynamically trust the algorithm or key source just because a token header specifies it. Keep keys in trusted configuration or a trusted key-discovery path linked to the expected issuer.</p><div class="notice"><strong>Decoder limit</strong>The <a href="/jwt-tools/">DevArea JWT inspector</a> can explain the claims and their timestamps; it does not validate the token's cryptographic signature or application policy.</div>''')],
[
('Are JWT fields mandatory?','No. The JWT specification defines registered claim names, but it does not require every token to include every registered claim. The application or protocol profile determines which claims are required.'),
('What is the difference between iss and aud?','iss identifies the issuer that created the token; aud identifies the recipient or recipients for whom the token is intended.'),
('What is the difference between exp, nbf and iat?','exp is the expiry time, nbf is the earliest time the token should be accepted, and iat is when it was issued.'),
('Are custom claims safe to trust?','Not by their presence alone. The token must be cryptographically and contextually validated, and the application must define how each custom claim affects behavior.'),
('What time unit does exp use?', "JWT NumericDate values are typically seconds from the Unix epoch. Use the specification and token issuer's contract if your system defines a profile-specific interpretation.")],
[('RFC 7519 — Registered Claim Names','https://datatracker.ietf.org/doc/html/rfc7519#section-4.1'),('OWASP JSON Web Token Cheat Sheet','https://cheatsheetseries.owasp.org/cheatsheets/JSON_Web_Token_for_Java_Cheat_Sheet.html'),('RFC 8725 — JWT Best Current Practices','https://www.rfc-editor.org/rfc/rfc8725.html')],
['jwt fields','jwt token fields','what is jwt token fields','jwt payload fields','jwt token parts'])

add_article('jwt-beautifier','JWT Beautifier: Format JSON and Inspect Token Claims','JWT Beautifier & Formatter Guide: Decode Without Guessing','Use a JWT beautifier to make token data readable. Learn what formatting reveals, how to handle errors, and why a JSON decode is not signature verification.','JWT / Tools',6,'28 October 2026',[
('what-is-beautifier','What is a JWT beautifier?', '''<p>A JWT beautifier is a developer utility that takes the compact token string and presents its parts in a readable form. It typically decodes the Base64url-encoded header and payload, pretty-prints the JSON, and makes claims such as <code class="inline-code">exp</code> or <code class="inline-code">aud</code> easier to inspect.</p><p>“Beautifying” and “validating” are different jobs. A beautifier formats data that can be decoded; a validator verifies the signature and applies an expected issuer, audience, time and application policy.</p>'''),
('use-it','How to use a JWT formatter', '''<ol><li>Copy the compact token from a controlled development environment. Avoid sharing live production credentials or logging them in a ticket.</li><li>Paste the raw value into the <a href="/jwt-tools/">JWT inspector</a>. A leading <code class="inline-code">Bearer</code> prefix is common in HTTP authorization headers and may be removed before decoding.</li><li>Inspect the header for algorithm and key metadata, then read the payload as JSON.</li><li>Review common claims and check whether timestamp values are seconds rather than milliseconds.</li><li>Use the output as a debugging clue, not as approval to accept the token.</li></ol>'''),
('format-output','What should a good beautifier show?', '''<p>A reliable utility should separate the header, payload and signature segment; preserve JSON types; show malformed inputs clearly; and avoid claiming to verify what it has not checked. Useful quality-of-life features include copying formatted JSON, inspecting standard time claims, accepting a common Bearer prefix and explaining the difference between signed JWS and encrypted JWE compact formats.</p><p>It should also state what happens to the input. This implementation decodes locally and does not request a remote decode API, but you should still consider the device and environment where you paste tokens.</p>'''),
('common-errors','Why does my JWT not format?', '''<ul><li><b>It is not a JWT:</b> an opaque access token may be a random string with no decodable JSON parts.</li><li><b>Missing or extra periods:</b> the value may have been truncated or may be an encrypted JWE rather than a three-part JWS.</li><li><b>Invalid characters:</b> copy the raw compact token without markup, smart quotes or line decorations.</li><li><b>JSON parsing fails:</b> Base64url decoding succeeded but the bytes did not form a JSON object.</li><li><b>It decodes but the API rejects it:</b> inspect server-side verification, key rotation, issuer, audience, expiry and application rules.</li></ul>'''),
('security','Security checklist after formatting', '''<p>After decoding, never assume that <code class="inline-code">sub</code> or <code class="inline-code">role</code> is authentic. Use a maintained library to verify the cryptographic signature with trusted keys and an explicit allowed-algorithm list. Validate claims required by your service, including issuer and audience when applicable, and make authorization decisions from validated context. Keep secrets and private key material out of the token itself and out of screenshots or logs.</p><p>The official <a href="https://cheatsheetseries.owasp.org/cheatsheets/JSON_Web_Token_for_Java_Cheat_Sheet.html">OWASP JWT guidance</a> is a useful security companion to the <a href="https://datatracker.ietf.org/doc/html/rfc7519">JWT specification</a>.</p>''')],
[
('Does a JWT beautifier change the token?','A formatter should only display a readable view of decoded parts; it should not silently modify the original token. Copy the original token separately if you need to preserve it.'),
('Can I format JWT without a secret?','Yes. Decoding the header and payload requires no secret key. The secret or public key is relevant to signature verification, which is a separate operation.'),
('What is the safest way to debug a production JWT?','Prefer a controlled environment and redacted diagnostics. Use trusted tooling and your service’s own verifier; avoid pasting live credentials into third-party tools unless your security policy permits it.'),
('What is the difference between a JWT decoder and a JWT validator?','A decoder reveals the structure and claims. A validator checks a signature and applies expected claim and application policies with trusted configuration.')],
[('JWT.io debugger','https://www.jwt.io/'),('RFC 7519 — JSON Web Token','https://datatracker.ietf.org/doc/html/rfc7519'),('OWASP JSON Web Token Cheat Sheet','https://cheatsheetseries.owasp.org/cheatsheets/JSON_Web_Token_for_Java_Cheat_Sheet.html')],
['jwt beautifier','jwt formatter','jwt token formatter','jwt decoder','jwt token explained'])

add_article('css-clamp-generator','CSS Clamp Generator: Create Fluid Values for Responsive Layouts','CSS Clamp Generator: Build Fluid Typography and Spacing','Learn how a CSS clamp generator turns minimum and maximum sizes into a fluid CSS value, how to pick viewport bounds, and how to test the output.','CSS / Generator',7,'28 October 2026',[
('what-generator-does','What does a CSS clamp generator do?', '''<p>A CSS clamp generator calculates a preferred value that scales with the viewport while staying between a minimum and maximum. It produces a rule such as <code class="inline-code">font-size: clamp(1rem, calc(0.5rem + 2vw), 3rem);</code>. The exact middle term depends on the size endpoints and viewport range you choose.</p><p>The CSS <code class="inline-code">clamp()</code> function takes three arguments: a lower bound, a preferred expression and an upper bound. The browser evaluates the preferred expression when it sits within the bounds, and uses a bound when it would otherwise go beyond the allowed range.</p>'''),
('choose-endpoints','Choose the size and viewport endpoints first', '''<p>Start by deciding the smallest and largest value that works for the actual design. Then choose the viewport widths at which those endpoints should apply. A heading might move from 32px on a narrow screen to 72px on a wide screen; a section gap might grow from 16px to 56px. Those are separate design decisions, even if the same formula generates both.</p><p>A common testing range is roughly 360px to 1440px, but it is not universal. Consider the smallest supported phone, the page's content width, large desktop screens and any design-specific breakpoints. The value stays clamped outside the range, so the endpoints matter as much as the formula.</p>'''),
('how-it-calculates','How the fluid calculation is generated', '''<p>The generator converts the size endpoints to a common unit, calculates a linear slope across the viewport interval, and finds an intercept that hits the minimum endpoint. The slope becomes a <code class="inline-code">vw</code> coefficient, while the intercept uses the chosen size unit.</p><div class="code-block"><div class="code-top"><span>ILLUSTRATIVE RESULT</span><span>REM OUTPUT</span></div><pre>font-size: clamp(
  1rem,
  calc(0.3333rem + 2.963vw),
  3rem
);</pre></div><p>For a 16px root font size, that example scales from 1rem (16px) at 360px viewport width to 3rem (48px) at 1440px. Values in between are fluid; the lower and upper clamp bounds apply outside that interval.</p>'''),
('what-to-generate','What can you generate besides font sizes?', '''<p>Use the generator for CSS properties that accept suitable length values: font size, padding, margin, gap, border radius and width are common examples. For typography, choose values that preserve readability and test long headings and translated content. For spacing, check that elements still align when the value changes.</p><p>A clamp rule changes a value smoothly; it does not replace structural responsive behavior. Use media or container queries where the layout itself needs to change, such as collapsing a navigation pattern or switching grid columns.</p>'''),
('units','rem or px: which output should you choose?', '''<p>For text sizing, rem-based bounds and intercepts are usually a sensible starting point because they are tied to the root font size. Pure viewport units can be difficult for users who enlarge text or zoom, because the value depends primarily on viewport dimensions. Pixel output may still be appropriate for some visual details, but it should be tested rather than assumed to be correct.</p><p>Accessibility guidance and implementation details matter: test at 200% zoom, check the design at the minimum and maximum, and make sure users can read the content without horizontal scrolling. The generator makes the arithmetic easier; it cannot decide whether the resulting scale is right for your content.</p>'''),
('use-generator','Use the calculator, then test the result', '''<ol><li>Choose minimum and maximum size values.</li><li>Set the viewport width for each endpoint.</li><li>Pick px or rem output and the CSS property you intend to style.</li><li>Move the preview slider and check how the design behaves across the range.</li><li>Copy the declaration into the real stylesheet, test it with the full page, and adjust bounds if the design breaks down.</li></ol><p>Try the <a href="/css-clamp-generator/">DevArea CSS clamp generator</a>, then read the <a href="/blog/css-clamp-calculator/">calculator formula guide</a> or the <a href="/blog/fluid-typography/">fluid typography article</a> for more detail.</p>''')],
[
('What is the best CSS clamp generator?','A useful generator should let you set size and viewport bounds, show its formula or output clearly, preview behavior at different widths, and provide output that you can test in your own design. The best fit depends on the workflow you need.'),
('Is CSS clamp supported in modern browsers?','The clamp() CSS value function has broad modern-browser support. Check MDN browser compatibility data for your supported browser targets.'),
('Can clamp be used for fluid typography?','Yes. It is commonly used to scale font-size between a minimum and maximum while avoiding a series of media-query steps for every intermediate size.'),
('Will clamp make my layout responsive by itself?','No. It makes an eligible value fluid. Layout structure, wrapping, columns and interaction patterns may still need media queries or container queries.')],
[('MDN — clamp() CSS function','https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Values/clamp'),('MDN — Using CSS math functions','https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Values_and_units/Using_math_functions'),('CSSClamp.com generator','https://cssclamp.com/')],
['css clamp generator','font size clamp generator','responsive css clamp','fluid typography calculator'])

add_article('css-clamp-calculator','CSS Clamp Calculator: Formula, Slope, Intercept and Examples','CSS Clamp Calculator: Understand the Math and Generate CSS','A practical CSS clamp calculator guide: see the formula, calculate slope and intercept, compare rem versus px, and work through a complete fluid-value example.','CSS / Calculator',8,'28 October 2026',[
('formula','The CSS clamp calculator formula', '''<p>A fluid clamp value can be built from two points: a minimum size at a minimum viewport width, and a maximum size at a maximum viewport width. The calculator finds the straight line that connects those points. It converts the line's slope into a viewport-relative <code class="inline-code">vw</code> coefficient and calculates the intercept.</p><div class="code-block"><div class="code-top"><span>FORMULA / INPUTS IN CONSISTENT PIXEL UNITS</span><span>CALCULATION</span></div><pre>vw coefficient = (max size − min size)
               ÷ (max viewport − min viewport)
               × 100

intercept = min size − (vw coefficient ÷ 100
                         × min viewport)

preferred = intercept + vw coefficient × 1vw</pre></div><p>When the size units are rem, the endpoints are first converted to pixels using the assumed root font size, then the intercept is converted back to rem for the output. This is why the root font-size assumption is part of a rem calculator.</p>'''),
('worked-example','Worked example: 1rem to 3rem', '''<p>Suppose the minimum size is 1rem and the maximum is 3rem, from a 360px viewport to a 1440px viewport. Assuming 1rem equals 16px, the pixel endpoints are 16px and 48px.</p><ol><li>Size change: 48 − 16 = 32px.</li><li>Viewport change: 1440 − 360 = 1080px.</li><li>VW coefficient: 32 ÷ 1080 × 100 ≈ 2.963.</li><li>Intercept: 16 − (2.963 ÷ 100 × 360) ≈ 5.333px, or 0.3333rem.</li></ol><div class="code-block"><div class="code-top"><span>RESULT / ROUNDED FOR READABILITY</span><span>CSS</span></div><pre>font-size: clamp(1rem, calc(0.3333rem + 2.963vw), 3rem);</pre></div><p>The browser is not required to display a rounded intermediate value exactly as the calculator text does. The formula's full-precision values and final bounds determine the result; a practical generator rounds the emitted CSS to a chosen number of decimal places.</p>'''),
('endpoint-check','Check the endpoints, not just the code', '''<p>At the minimum viewport, the preferred expression should equal the minimum size. At the maximum viewport, it should equal the maximum size. Between those widths, the preferred value should move linearly. Outside the range, <code class="inline-code">clamp()</code> holds the value at the minimum or maximum.</p><p>A preview slider makes these points easy to inspect. It is not enough to generate syntactically valid CSS; test the layout where the value changes fastest and where content is close to wrapping.</p>'''),
('rem-px','Why rem and px output differ', '''<p>CSS px is a CSS reference pixel; rem is relative to the root element's font size. If you choose rem output, the generator must use a root font-size assumption to map the viewport endpoints to the rem line. The output will then scale with the actual root font size in the browser. If the page's root font size is different from the assumption, the exact match at the selected viewport endpoints will differ from the calculator's sample.</p><p>That is not a reason to avoid rem. It's a reason to state the assumption and test under realistic browser settings. For fluid type, relative units can make the interface more responsive to the reader's font-size preference.</p>'''),
('bad-ranges','Common calculator mistakes', '''<ul><li><b>Max size is less than or equal to min size:</b> the normal increasing fluid scale has no positive range to interpolate.</li><li><b>Viewport max is not greater than viewport min:</b> slope calculation divides by a zero or negative interval.</li><li><b>Wrong units:</b> subtracting a rem value directly from a px value without conversion creates incorrect math.</li><li><b>Too many decimals:</b> copy becomes noisy and hard to maintain; precision should be sufficient for the design, not arbitrary.</li><li><b>Ignoring real content:</b> a fluid value can still cause awkward wrapping or spacing when the text, language or component changes.</li></ul>'''),
('calculate-now','Use the CSS clamp calculator', '''<p>Set the values, review the generated declaration and move the preview slider through the intended viewport range. If the result looks abrupt at a real breakpoint, consider changing the endpoints or combining clamp with a breakpoint rather than forcing a single function to handle a structural layout change.</p><p>Open the <a href="/css-clamp-generator/">live CSS clamp calculator</a> to calculate your values, or review the <a href="/blog/css-clamp-examples/">worked CSS clamp examples</a> for typography and layout properties.</p>''')],
[
('How do I calculate a clamp value by hand?','Convert the size endpoints to one unit, calculate (max size minus min size) divided by (max viewport minus min viewport) and multiply by 100 to get the vw coefficient. Then calculate the intercept from the minimum size and minimum viewport.'),
('Can the intercept be negative?','Yes. A negative intercept can be mathematically correct for some endpoint combinations. It should still be tested in the intended CSS property and viewport range.'),
('Why does the generated value use calc()?','calc() combines a fixed intercept with a viewport-relative term. clamp() then limits the computed preferred value to the minimum and maximum.'),
('How many decimals should a calculator output?','Enough to make the interpolation accurate for the design. Three or four decimal places are often readable; test the rounded output at both endpoints and relevant in-between widths.')],
[('MDN — clamp()','https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Values/clamp'),('MDN — CSS math functions','https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Values_and_units/Using_math_functions'),('CSSClamp.com — generator and formula notes','https://cssclamp.com/')],
['clamp calculator','css clamp calculator','css clamp formula','clamp calculator for fluid typography'])

add_article('fluid-typography','Fluid Typography With CSS clamp(): A Practical Guide','Fluid Typography with CSS clamp() — Responsive Type That Reads Well','Learn to design fluid typography with CSS clamp(), choose minimum and maximum font sizes, use rem-based values, test browser zoom, and build a consistent type scale.','CSS / Typography',7,'28 October 2026',[
('what-fluid-type','What is fluid typography?', '''<p>Fluid typography lets text size change gradually with the available viewport instead of jumping only at a few breakpoints. A CSS <code class="inline-code">clamp()</code> expression can set a minimum size, a preferred viewport-responsive value and a maximum size, so a heading grows smoothly but remains bounded.</p><p>Fluid doesn't automatically mean accessible or well-designed. The endpoints, the content, line length, font metrics and user text settings still shape whether the result is readable. The goal is a type scale that adapts without losing hierarchy.</p>'''),
('choose-scale','Choose a type scale, not just a number', '''<p>Begin with a hierarchy: body text, small labels, section headings and the main page title. Decide how each role should feel on the narrowest supported screen and at the desktop size. Don't start with a huge maximum and hope the result will look editorial; test headings that wrap across two or three lines, and check layouts with real titles.</p><p>One possible system is a body size that moves from 1rem to 1.125rem, a section heading from 1.75rem to 3rem, and a display heading from 2.75rem to 5rem. Those ranges are examples, not universal rules. Your font family, content width and brand style may need different endpoints.</p>'''),
('write-clamp','Write the clamp rule', '''<p>A typical font-size rule has this shape:</p><div class="code-block"><div class="code-top"><span>CSS / FLUID HEADING</span><span>REM BOUNDS</span></div><pre>.page-title {
  font-size: clamp(2.25rem, calc(1.4rem + 3vw), 4.75rem);
  line-height: 0.98;
  letter-spacing: -0.06em;
}</pre></div><p>The middle term is a preferred size. You can calculate it manually, use a <a href="/css-clamp-generator/">CSS clamp generator</a>, or adapt a value from a design system. Line height and tracking are separate decisions; they should be tested alongside the font-size value.</p>'''),
('accessibility','Make fluid type work with zoom and text resizing', '''<p>A size expressed only in viewport units may not respond the way a user expects when they zoom or enlarge text. Relative bounds and a relative intercept are a stronger starting point for fluid typography. Follow the accessibility guidance for text scaling and verify that the maximum font size can grow sufficiently relative to the minimum.</p><p>Test at 200% browser zoom, with an enlarged default font size, and on a narrow screen. Check that content does not overlap, become clipped, or require unnecessary horizontal scrolling. Avoid setting a minimum so small that the page is hard to read and a maximum so large that paragraphs become difficult to scan.</p>'''),
('choose-viewports','Choose the viewport boundaries', '''<p>The viewport endpoints should correspond to where the size should stop shrinking and stop growing—not simply to whichever values the calculator starts with. A range like 360px to 1440px is a practical test baseline for many layouts, but some components have narrower ranges and others scale across larger desktop canvases.</p><p>Use browser responsive mode to test a few intermediate widths in addition to the endpoints. A fluid formula can be correct while an adjacent grid, image or paragraph wraps poorly; responsive design is the whole composition, not only the font-size declaration.</p>'''),
('when-to-use','When to use clamp versus media queries', '''<p>Use clamp for a value that should transition smoothly—such as font size, spacing, gap or width. Use media or container queries when the composition needs a discrete change: navigation collapses, grid columns stack, controls move, or a component needs a different arrangement.</p><p>These approaches complement each other. A page can change from three columns to one at a breakpoint while each card's internal heading scales fluidly with clamp. The right tool is determined by whether the change is continuous in value or structural in layout.</p>''')],
[
('Is clamp good for responsive typography?','It can be. It makes the font size vary continuously between bounds. Choose the scale intentionally and test actual copy at small and large widths, zoom levels and user font settings.'),
('Should fluid typography use rem or px?','Rem-based bounds and intercepts are a strong default for text because they relate to the root font size. Whatever units you use, test text enlargement and browser zoom.'),
('Should I use clamp on every heading?','No. Use it where continuous scaling improves the design. A small label may not benefit from fluid behavior, and some headings can use a fixed size or a breakpoint-based change.'),
('How do I avoid oversized headings on desktop?','Set a maximum that matches your content width and type hierarchy, preview the longest heading and verify line breaks at intermediate widths. The maximum clamp bound is an explicit design decision.')],
[('MDN — clamp() CSS function','https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Values/clamp'),('MDN — Using CSS math functions','https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Values_and_units/Using_math_functions'),('MDN — WCAG text resize note on clamp()','https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Values/clamp#accessibility')],
['fluid typography','font size clamp generator','responsive typography css','css clamp font size'])

add_article('css-clamp-examples','CSS clamp() Examples for Font Size, Spacing, Gap and Width','CSS clamp() Examples: Responsive Typography and Spacing','Copy and adapt practical CSS clamp() examples for font sizes, section padding, gaps, margins, border radius and widths, with notes on where each fits.','CSS / Examples',8,'28 October 2026',[
('examples-overview','How to read these CSS clamp examples', '''<p>Each example uses three values: a minimum, a preferred expression and a maximum. Values between the bounds change fluidly with viewport width; values beyond the bounds stop at the limit. Treat the values below as starting points, not universal design tokens. Test them with your font, content and layout.</p><p>The preferred terms shown are illustrative. Use a <a href="/css-clamp-generator/">CSS clamp calculator</a> to generate the middle expression from the exact endpoints you want in your project.</p>'''),
('font-size-examples','1. Font size: fluid heading and body', '''<div class="code-block"><div class="code-top"><span>DISPLAY HEADING</span><span>CSS</span></div><pre>.hero-title {
  font-size: clamp(2.75rem, calc(1.8rem + 3.5vw), 5rem);
  line-height: 0.96;
  letter-spacing: -0.065em;
}</pre></div><div class="code-block"><div class="code-top"><span>BODY COPY</span><span>CSS</span></div><pre>body {
  font-size: clamp(1rem, calc(0.96rem + 0.18vw), 1.125rem);
  line-height: 1.7;
}</pre></div><p>Headings often need a wider scale than body copy. Preview the longest heading and check where its line breaks occur. Keep body text readable and avoid making every size fluid just because the function exists.</p>'''),
('spacing-examples','2. Section padding and component gap', '''<div class="code-block"><div class="code-top"><span>SECTION PADDING</span><span>CSS</span></div><pre>.section {
  padding-block: clamp(3rem, calc(1.5rem + 4vw), 6.5rem);
  padding-inline: clamp(1rem, calc(0.5rem + 2vw), 2.5rem);
}</pre></div><div class="code-block"><div class="code-top"><span>GRID GAP</span><span>CSS</span></div><pre>.card-grid {
  gap: clamp(0.75rem, calc(0.45rem + 1vw), 1.75rem);
}</pre></div><p>Fluid spacing can reduce wasted space on small screens while leaving comfortable breathing room on wide screens. Make sure large padding does not squeeze the content column and small gaps still preserve separation.</p>'''),
('margin-width','3. Margin, width and border radius', '''<div class="code-block"><div class="code-top"><span>COMPONENT WIDTH</span><span>CSS</span></div><pre>.content-panel {
  width: min(100%, clamp(18rem, 70vw, 68rem));
  margin-inline: auto;
}</pre></div><div class="code-block"><div class="code-top"><span>BORDER RADIUS</span><span>CSS</span></div><pre>.feature-panel {
  border-radius: clamp(0.5rem, calc(0.3rem + 0.6vw), 1rem);
}</pre></div><p>Width expressions often combine clamp with <code class="inline-code">min()</code>, <code class="inline-code">max()</code> or container constraints. Confirm the property allows the units you use and the result doesn't exceed its parent. Border radius can scale subtly, but it rarely needs a dramatic range.</p>'''),
('when-media','4. When a media query is still the right tool', '''<p>Don't try to solve a structural layout change with a fluid scalar. A three-column card grid may use clamp for its gap, while media queries decide when it becomes two columns or one. A header may use fluid logo sizing while a breakpoint changes its navigation pattern.</p><div class="code-block"><div class="code-top"><span>COMBINE FLUID VALUES AND BREAKPOINTS</span><span>CSS</span></div><pre>.grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(0.75rem, 1.5vw, 1.5rem);
}
@media (max-width: 48rem) {
  .grid { grid-template-columns: 1fr; }
}</pre></div>'''),
('testing','5. A practical test checklist', '''<ul><li>Check the minimum, maximum and at least three intermediate widths.</li><li>Test long headings, long words, translated content and user-generated text.</li><li>Verify 200% zoom and a larger root font size.</li><li>Check that padding or width does not cause horizontal overflow.</li><li>Keep generated declarations consistent with your token and naming strategy.</li><li>Use browser devtools to inspect computed values when a result behaves unexpectedly.</li></ul><p>For the arithmetic behind the preferred term, read the <a href="/blog/css-clamp-calculator/">CSS clamp calculator guide</a>. For typography-specific choices, read <a href="/blog/fluid-typography/">fluid typography with clamp()</a>.</p>''')],
[
('Can I use clamp for padding and margin?','Yes. clamp() works for properties that accept suitable length values, including padding, margin and gap.'),
('Can clamp be combined with min() or max()?','Yes. CSS math functions can be combined where the property grammar permits it. Test the full expression in the target browser and property.'),
('Should I use clamp for width?','It can work for width when fluid size is appropriate, often alongside max-width constraints. Ensure the component still fits its container and does not force horizontal overflow.'),
('Why should I still test responsive breakpoints?','Clamp changes a value continuously; media queries and container queries handle structural layout changes. A production layout often needs both.')],
[('MDN — clamp()','https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Values/clamp'),('MDN — CSS math functions','https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Values_and_units/Using_math_functions')],
['css clamp examples','css clamp for padding','css clamp for font size','clamp css spacing'])

# Render article pages and schema. Article headings have stable anchor IDs for TOC.
def article_path(slug): return f'/blog/{slug}/'
def render_article(a):
    toc=''
    content=[]
    for sid,heading,body in a['sections']:
        content.append(f'<h2 id="{sid}">{heading}</h2>{body}')
    faq_html=''.join(f'<details><summary>{esc(q)}</summary><p>{esc(ans)}</p></details>' for q,ans in a['faqs'])
    sources_html=''.join(f'<li><a href="{url}" target="_blank" rel="noopener noreferrer">{esc(name)}</a></li>' for name,url in a['sources'])
    crumbs=breadcrumb_schema([('Home','/'),('Field notes','/blog/'),(a['title'],article_path(a['slug']))])
    schema={"@context":"https://schema.org","@type":"TechArticle","headline":a['title'],"description":a['description'],"datePublished":"2026-10-28","dateModified":"2026-10-28","author":{"@type":"Organization","name":"DevArea Tools","url":BASE+"/about/"},"publisher":{"@type":"Organization","name":"DevArea Tools","url":BASE+"/"},"mainEntityOfPage":BASE+article_path(a['slug']),"keywords":', '.join(a['keywords']),"inLanguage":"en"}
    body=f'''<section class="article-hero"><div class="narrow"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a><span aria-hidden="true">/</span><a href="/blog/">Field notes</a><span aria-hidden="true">/</span><span>{esc(a['category'])}</span></nav><div class="article-kicker">{esc(a['category'])} / FIELD NOTE</div><h1>{esc(a['title'])}</h1><p class="article-dek">{esc(a['description'])}</p><div class="article-meta"><span>{a['minutes']} min read</span><span>Updated {esc(a['updated'])}</span><span>Reference-led guide</span></div></div></section><section class="article-layout"><aside class="toc"><h2>On this page</h2><nav data-toc aria-label="Article contents"></nav><div style="margin-top:22px;padding-top:17px;border-top:1px solid var(--line)"><span class="eyebrow" style="font-size:9px">Use the tool</span><p class="small muted">Apply the guide to a live example.</p>{'<a class="text-link" href="/jwt-tools/">Open JWT inspector <span>↗</span></a>' if a['slug'].startswith('jwt') else '<a class="text-link" href="/css-clamp-generator/">Open clamp generator <span>↗</span></a>'}</div></aside><article class="article-body" data-article-body><div class="answer-card"><strong>Quick answer</strong>{esc(a['description'])}</div>{''.join(content)}<div class="article-sources"><h2>References and further reading</h2><p>Primary standards and documentation used to support this guide.</p><ul>{sources_html}</ul></div><div class="article-sources"><h2>Frequently asked questions</h2><div class="faq-list">{faq_html}</div></div><div class="article-sources"><div class="eyebrow">Keep learning</div><h2>Put the explanation to work.</h2><p>{'Inspect a token in the browser-based JWT formatter, then use the claims reference when you need to understand a field.' if a['slug'].startswith('jwt') else 'Generate the value with live preview, then test it in the context of your actual design.'}</p><p><a class="btn btn-dark" href="{'/jwt-tools/' if a['slug'].startswith('jwt') else '/css-clamp-generator/'}">{'Open JWT inspector' if a['slug'].startswith('jwt') else 'Open CSS clamp generator'} <span aria-hidden="true">↗</span></a></p></div></article></section><section class="related-guides"><div class="wrap"><div class="section-heading"><div><div class="eyebrow">Related field notes</div><h2>Continue where this leaves off.</h2></div><p>Build a fuller understanding by following the next practical question in the topic.</p></div><div class="related-grid"><a class="related-card" href="{'/blog/jwt-token-parts/' if a['slug'].startswith('jwt') else '/blog/css-clamp-calculator/'}"><div class="eyebrow">Read next</div><h3>{'JWT token parts, explained' if a['slug'].startswith('jwt') else 'CSS clamp calculator: the formula'}</h3><p>{'Understand the compact token structure and why the signature needs a verifier.' if a['slug'].startswith('jwt') else 'Follow the slope and intercept from size endpoints to a complete CSS declaration.'}</p><span class="related-arrow">↗</span></a><a class="related-card" href="{'/blog/jwt-fields/' if a['slug'].startswith('jwt') else '/blog/fluid-typography/'}"><div class="eyebrow">Go deeper</div><h3>{'JWT claims and fields reference' if a['slug'].startswith('jwt') else 'Fluid typography with clamp()'}</h3><p>{'Look up common registered claims, their meaning and validation requirements.' if a['slug'].startswith('jwt') else 'Turn the calculation into a readable, consistent type scale.'}</p><span class="related-arrow">↗</span></a><a class="related-card" href="/blog/"><div class="eyebrow">Field notes / index</div><h3>Browse the full library</h3><p>See all developer guides and choose your next question.</p><span class="related-arrow">↗</span></a></div></div></section>'''
    return page(a['meta'],a['description'],article_path(a['slug']),body,active='/blog/',light_header=True,schemas=[org_schema(),website_schema(),schema,faq_schema(a['faqs']),crumbs])

for a in articles:
    write(f'blog/{a["slug"]}/index.html',render_article(a))

blog_index_items=''.join(f'''<a class="blog-item" href="{article_path(a['slug'])}" data-blog-item data-category="{'jwt' if a['slug'].startswith('jwt') else 'css'}" data-search="{esc((a['title']+' '+a['description']+' '+' '.join(a['keywords'])).lower())}"><span class="blog-item-number">{len(articles)-i:02d}</span><span class="blog-item-category">{esc(a['category'])}</span><span><span class="blog-item-title">{esc(a['title'])}</span><span class="blog-item-desc">{esc(a['description'])}</span></span><span class="blog-item-meta">{a['minutes']} MIN READ<br><span style="display:block;font-size:17px;margin-top:8px">↗</span></span></a>''' for i,a in enumerate(articles))
