def simple(title,desc,path,headline,lead,prose,active='',schemas=None,light=True):
    body=f'<section class="simple-page"><div class="narrow"><div class="eyebrow">DevArea Tools / {esc(title)}</div><h1>{headline}</h1><p class="simple-lead">{lead}</p><div class="prose">{prose}</div></div></section>'
    return page(title+' | DevArea Tools',desc,path,body,active=active,light_header=light,schemas=[org_schema(),website_schema()]+(schemas or []))

about_prose=f'''<h2>Why this exists</h2><p>DevArea Tools is a small, focused utility project by <a href="https://devareayt.in/">DevArea</a>. It started with two practical developer needs that are easy to underestimate: making JWT structure readable while preserving the difference between decoding and verification, and calculating fluid CSS values without repeatedly doing the same arithmetic by hand.</p><p>The project is deliberately narrow at launch. A short list of useful tools is easier to test, explain and maintain than a directory of superficial utilities. The aim is to expand when a tool can solve a real job and provide a clear answer.</p><h2>How the tools are built</h2><ul><li><b>Local-first:</b> the JWT parser and clamp calculator run in the browser with plain JavaScript.</li><li><b>Explain the limits:</b> a decoded JWT is not a verified token; generated CSS still needs testing in its design context.</li><li><b>Prefer standards:</b> technical guides link to primary documentation and recognized security guidance.</li><li><b>Performance conscious:</b> the pages are static HTML, CSS and JavaScript with no required framework runtime, font download or remote decoding API.</li></ul><h2>Who maintains it?</h2><p>DevArea is an independent digital development studio. This tool project is maintained as part of that ecosystem and connected to <a href="https://epsingh.in/">Ekansh Pratap Singh's web development work</a>. Feedback about an incorrect result, confusing explanation or accessibility issue is welcome.</p><p><a class="btn btn-dark" href="/contact/">Contact the project ↗</a></p>'''
write('about/index.html',simple('About','About DevArea Tools, a focused browser-based project for JWT inspection, responsive CSS generation and practical developer education.','/about/','Small tools.<br>Clear thinking.', 'DevArea Tools is an independent utility project for developers and designers who want a usable result and the context to use it correctly.',about_prose,active='/about/'))
contact_prose=f'''<h2>Contact the project</h2><p>For bug reports, questions about the tools, corrections to a guide, or suggestions for a future utility, email the project maintainer.</p><div class="contact-panel"><div class="contact-method"><small>Project email</small><h2>Technical feedback</h2><p>Describe the browser, the steps that reproduce the issue, and the expected result. Please redact tokens, secrets and personal data.</p><a href="mailto:{EMAIL}?subject=DevArea%20Tools%20feedback">{EMAIL} ↗</a></div><div class="contact-method"><small>Built by</small><h2>DevArea</h2><p>For website development, digital products or agency enquiries, use the DevArea website.</p><a href="https://devareayt.in/">devareayt.in ↗</a></div></div><h2>Responsible disclosure</h2><p>Do not send working production credentials or private keys in a bug report. For a security concern, explain the behavior and provide a sanitized reproduction without exposing tokens or secrets.</p>'''
write('contact/index.html',simple('Contact','Contact DevArea Tools with a bug report, correction, suggestion or question about the JWT inspector and CSS clamp generator.','/contact/','Tell us what<br>needs attention.', 'Useful feedback is specific: what you tried, what happened, and what you expected instead. Please do not send credentials or production tokens.',contact_prose,active='/contact/'))
security_prose='''<h2>JWT processing</h2><p>The JWT inspector decodes the visible header and payload locally with JavaScript. It does not call a JWT decoding API, and it does not verify a token signature, issuer, audience or authorization policy. The generated inspection view may contain sensitive claims, so avoid taking screenshots or sharing copied output with credentials intact.</p><h2>CSS clamp calculation</h2><p>The CSS clamp generator performs arithmetic in the browser. Values you enter are used to calculate and preview a CSS declaration; the page does not need a server to calculate the result.</p><h2>What this site does not promise</h2><p>Local processing is not a guarantee that the device, browser extensions, operating system, clipboard or surrounding environment is secure. Use a trusted device, keep software updated and avoid exposing production tokens in shared environments.</p><p>The tools are for inspection and development assistance. They do not replace application-level validation, security review, browser testing or accessibility evaluation.</p><h2>Security questions</h2><p>Send a sanitized description to <a href="mailto:ekanshprataps@gmail.com?subject=DevArea%20Tools%20security%20question">ekanshprataps@gmail.com</a>. Do not include passwords, live tokens, secrets or private keys.</p><h2>Technical references</h2><ul><li><a href="https://cheatsheetseries.owasp.org/cheatsheets/JSON_Web_Token_for_Java_Cheat_Sheet.html">OWASP JWT security guidance</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc7519">RFC 7519: JSON Web Token</a></li><li><a href="https://www.rfc-editor.org/rfc/rfc8725.html">RFC 8725: JWT Best Current Practices</a></li></ul>'''
write('security/index.html',simple('Security','Security practices for DevArea Tools, including local JWT decoding, client-side CSS calculations, limitations and responsible disclosure.','/security/','Clear about what<br>happens to your data.', 'The tools are designed to work locally in your browser. This page explains the processing boundaries and their limits.',security_prose,active='/security/'))
privacy_prose='''<p><b>Last updated: 28 October 2026.</b></p><h2>Information you enter into the tools</h2><p>The JWT inspector and CSS clamp generator are designed to process their inputs in your browser. The source code does not send JWT tokens or calculator inputs to a decoding or calculation endpoint. Do not assume that local processing makes a shared device or browser extension safe; protect credentials and close the page when you finish.</p><h2>Contact messages</h2><p>This static site uses an email link for contact rather than a built-in contact form. If you choose to email the maintainer, the information in that message is handled by your email provider and the recipient's email service.</p><h2>Hosting and server logs</h2><p>The hosting provider may process technical request data such as IP address, user-agent, requested path and timestamps as part of normal delivery and security logging. The exact retention and processing details depend on the production hosting provider and its settings; review the provider's current privacy terms.</p><h2>Cookies, analytics and advertising</h2><p>The source bundle does not include an analytics SDK, advertising pixel, account system or intentional cookie-based tracking. If these are added later, this policy should be updated before publication. The hosting platform or linked external sites may have their own policies.</p><h2>External links</h2><p>Links to documentation, DevArea and the personal developer blog lead to other websites. Their content and data handling are governed by those sites, not this project.</p><h2>Changes</h2><p>This policy may be updated when features or hosting practices change. The date at the top should be refreshed when a material change is published.</p><p>Questions: <a href="mailto:ekanshprataps@gmail.com?subject=DevArea%20Tools%20privacy">ekanshprataps@gmail.com</a>.</p>'''
write('privacy-policy/index.html',simple('Privacy policy','Privacy policy for DevArea Tools, describing local browser processing, contact emails, hosting logs, cookies and external links.','/privacy-policy/','A straightforward note<br>about privacy.', 'The tools are built to keep inputs in the browser. This policy explains what that does—and does not—mean.',privacy_prose,active='/privacy-policy/'))
terms_prose='''<p><b>Last updated: 28 October 2026.</b></p><h2>Use of the site</h2><p>DevArea Tools provides browser-based developer utilities and educational material. You may use the generated output in personal and commercial projects, subject to your own testing and the terms of any relevant third-party tools or services.</p><h2>No security or production guarantee</h2><p>The JWT inspector decodes token data but does not verify signatures or certify validity. A CSS clamp value is calculated from the values you provide and may need adaptation. You are responsible for testing output in your application and for following your own security, accessibility and compliance requirements.</p><h2>No warranty</h2><p>The site and its utilities are provided on an “as is” and “as available” basis to the extent permitted by applicable law. We do not guarantee that every input or browser environment will be supported or that the service will be uninterrupted, error-free or suitable for a particular purpose.</p><h2>Acceptable use</h2><p>Do not use the site to violate laws, attempt to compromise the site or other systems, or share credentials and private information without authorization. The tools are not intended to replace a maintained production security library.</p><h2>External sources</h2><p>Technical guides may link to third-party documentation. Links are provided for reference; their availability and terms are controlled by their respective publishers.</p><h2>Updates and contact</h2><p>Terms may change as features evolve. For questions, contact <a href="mailto:ekanshprataps@gmail.com">ekanshprataps@gmail.com</a>.</p>'''
write('terms/index.html',simple('Terms & conditions','Terms and conditions for using the DevArea Tools browser-based developer utilities, educational content and generated output.','/terms/','Use the tools.<br>Own the final check.', 'These tools help with inspection and calculation. You remain responsible for validating their output in context.',terms_prose,active='/terms/'))
cookies_prose='''<p><b>Last updated: 28 October 2026.</b></p><h2>Cookie use in this release</h2><p>The published source does not intentionally set analytics, advertising or preference cookies. The utilities work without an account and do not require a cookie to preserve JWT or CSS calculator inputs between page loads.</p><h2>Hosting and third-party services</h2><p>The hosting provider or external websites you visit from links may set or process cookies under their own practices. Those behaviors are controlled by the provider and its current deployment settings, not by this static website source.</p><h2>If tracking is introduced later</h2><p>Any future analytics, advertising or preference storage should be reviewed before being added. This page should be updated to describe the actual technologies and controls in the deployed site.</p><p>Questions: <a href="mailto:ekanshprataps@gmail.com?subject=DevArea%20Tools%20cookies">ekanshprataps@gmail.com</a>.</p>'''
write('cookies/index.html',simple('Cookies','Cookie information for DevArea Tools, including the current static site behavior and hosting-provider caveats.','/cookies/','No tracking layer<br>in the source bundle.', 'This release does not intentionally set analytics or advertising cookies. Hosting behavior may differ by deployment.',cookies_prose,active='/cookies/'))
press_prose='''<h2>About the project</h2><p>DevArea Tools is a small browser-first project maintained by DevArea. The first release focuses on JWT inspection and responsive CSS clamp generation, supported by source-linked technical guides.</p><h2>Project facts</h2><ul><li><b>Project:</b> DevArea Tools</li><li><b>Website:</b> <a href="https://tools.devareayt.in/">tools.devareayt.in</a></li><li><b>Maintainer:</b> DevArea</li><li><b>Focus:</b> developer utilities and educational reference material</li><li><b>Contact:</b> <a href="mailto:ekanshprataps@gmail.com">ekanshprataps@gmail.com</a></li></ul><h2>Editorial and technical notes</h2><p>Guides link to primary standards and documentation where relevant. The JWT inspector decodes token contents but does not verify token signatures. The CSS clamp generator calculates values based on user-supplied endpoints and should be tested in the target layout.</p><p>This page is a concise project fact sheet rather than a claim of press coverage or user metrics.</p>'''
